using Bank.Application.Abstractions;
using Bank.Application.Common;

namespace Bank.Infrastructure.Storage;

public record StorageOptions(string Root = "storage");

/// <summary>
/// Files on the local disk (a Docker volume in compose). Swap for S3/Azure Blob in production;
/// paths are relative and generated by the application, never taken from user input.
/// </summary>
internal class LocalFileStorage(StorageOptions options) : IFileStorage
{
    private readonly string _root = Path.GetFullPath(options.Root);

    public async Task SaveAsync(string path, Stream content, CancellationToken ct)
    {
        var fullPath = Resolve(path);
        Directory.CreateDirectory(Path.GetDirectoryName(fullPath)!);
        await using var file = File.Create(fullPath);
        await content.CopyToAsync(file, ct);
    }

    public Task<Stream> OpenReadAsync(string path, CancellationToken ct)
    {
        var fullPath = Resolve(path);
        if (!File.Exists(fullPath)) throw new NotFoundException("Arquivo não encontrado.");
        return Task.FromResult<Stream>(File.OpenRead(fullPath));
    }

    private string Resolve(string path)
    {
        var fullPath = Path.GetFullPath(Path.Combine(_root, path));
        // Defense in depth against path traversal ("../").
        if (!fullPath.StartsWith(_root + Path.DirectorySeparatorChar, StringComparison.Ordinal))
            throw new InvalidOperationException("Invalid storage path.");
        return fullPath;
    }
}
